DROP TABLE IF EXISTS `classes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `classes` (
  `id` varchar(50) NOT NULL,
  `name` varchar(50) NOT NULL,
  `grade_level` tinyint(3) unsigned NOT NULL,
  `cohort` varchar(20) DEFAULT NULL,
  `school_year_id` varchar(50) NOT NULL,
  `semester_id` varchar(50) DEFAULT NULL,
  `homeroom_teacher_id` varchar(50) DEFAULT NULL,
  `capacity` smallint(5) unsigned NOT NULL DEFAULT 45,
  `status` varchar(20) NOT NULL DEFAULT 'draft',
  `locked_at` timestamp NULL DEFAULT NULL,
  `archived_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `classes_year_semester_name_unique` (`school_year_id`,`semester_id`,`name`),
  KEY `classes_school_year_idx` (`school_year_id`),
  KEY `classes_homeroom_fk` (`homeroom_teacher_id`),
  KEY `classes_semester_id_index` (`semester_id`),
  KEY `classes_status_index` (`status`),
  KEY `classes_cohort_index` (`cohort`),
  CONSTRAINT `classes_homeroom_fk` FOREIGN KEY (`homeroom_teacher_id`) REFERENCES `teachers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `classes_school_year_fk` FOREIGN KEY (`school_year_id`) REFERENCES `school_years` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

